import { Controller, Get, Post, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const ROLE = '예산·회계 담당자';
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;
// 가정: 거래처가 지정된 전표 분개를 채권·채무로 본다.
// 가정: 잔액 = 분개 금액 - 상계 누계.
const BALANCE_SQL =
  '(vl.amount - COALESCE((SELECT SUM(ro.offset_amount) FROM receivable_offset ro WHERE ro.voucher_line_id = vl.voucher_line_id), 0))';
// 가정: 연령분석 구간은 30일 단위로 나눈다.
const AGING_SQL =
  "CASE WHEN (CAST(:baseDate AS date) - jv.voucher_date) <= 30 THEN '30일 이내' " +
  "WHEN (CAST(:baseDate AS date) - jv.voucher_date) <= 60 THEN '31~60일' " +
  "WHEN (CAST(:baseDate AS date) - jv.voucher_date) <= 90 THEN '61~90일' " +
  "ELSE '90일 초과' END";

function invalid(message: string): ApiError {
  return new ApiError(400, 'VALIDATION_FAILED', message);
}

function isIntegerText(value: unknown): boolean {
  return /^\d+$/.test(String(value));
}

@Controller('api/v1')
export class FnSfr00808Controller {
  @Get('/receivable-balances')
  async listReceivableBalances(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const query = checks.queryOf(req.query);
    const baseDate = query['baseDate'];
    if (typeof baseDate !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(baseDate)) {
      throw invalid('기준일자를 YYYY-MM-DD 형식으로 입력해 주세요.');
    }
    const pageText = query['page'] === undefined || query['page'] === '' ? '0' : String(query['page']);
    const sizeText =
      query['size'] === undefined || query['size'] === '' ? String(DEFAULT_SIZE) : String(query['size']);
    if (!isIntegerText(pageText) || !isIntegerText(sizeText)) {
      throw invalid('page와 size는 0 이상의 정수여야 합니다.');
    }
    const page = Number(pageText);
    const size = Math.min(Number(sizeText), MAX_SIZE);
    if (size < 1) {
      throw invalid('size는 1 이상이어야 합니다.');
    }
    const params: Record<string, unknown> = { baseDate };
    let where =
      "WHERE vl.partner_id IS NOT NULL AND jv.status <> '승인해제' " +
      'AND jv.voucher_date <= CAST(:baseDate AS date) AND ' +
      BALANCE_SQL +
      ' > 0';
    const partnerId = query['partnerId'];
    if (partnerId !== undefined && partnerId !== '') {
      if (!isIntegerText(partnerId)) {
        throw invalid('거래처 값이 올바르지 않습니다.');
      }
      params['partnerId'] = String(partnerId);
      where += ' AND vl.partner_id = CAST(:partnerId AS bigint)';
    }
    const accountItemId = query['accountItemId'];
    if (accountItemId !== undefined && accountItemId !== '') {
      if (!isIntegerText(accountItemId)) {
        throw invalid('계정과목 값이 올바르지 않습니다.');
      }
      params['accountItemId'] = String(accountItemId);
      where += ' AND vl.account_item_id = CAST(:accountItemId AS bigint)';
    }
    const joins =
      'FROM voucher_line vl ' +
      'JOIN journal_voucher jv ON jv.journal_voucher_id = vl.journal_voucher_id ' +
      'JOIN account_item ai ON ai.account_item_id = vl.account_item_id ' +
      'LEFT JOIN partner p ON p.partner_id = vl.partner_id ';
    return transaction(async (db) => {
      const rows = await db.query(
        'SELECT vl.voucher_line_id AS "voucherLineId", ' +
          'p.partner_name AS "partnerName", ' +
          'ai.account_name AS "accountName", ' +
          BALANCE_SQL +
          ' AS "balance", ' +
          AGING_SQL +
          ' AS "agingBucket" ' +
          joins +
          where +
          ' ORDER BY vl.voucher_line_id LIMIT CAST(:size AS integer) OFFSET CAST(:offset AS integer)',
        { ...params, size: String(size), offset: String(page * size) },
      );
      const counts = await db.query('SELECT COUNT(*) AS "total" ' + joins + where, params);
      const items = rows.map((row: Record<string, unknown>) => ({
        voucherLineId: Number(row['voucherLineId']),
        partnerName: row['partnerName'],
        accountName: row['accountName'],
        balance: Number(row['balance']),
        agingBucket: row['agingBucket'],
      }));
      return { items, page, size, total: Number(counts[0]['total']) };
    });
  }

  @Post('/receivable-offsets')
  @HttpCode(200)
  async createReceivableOffset(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const data = checks.inputOf(req.body);
    const voucherLineId = data['voucherLineId'];
    const offsetAmount = data['offsetAmount'];
    if (voucherLineId === undefined || voucherLineId === null || !isIntegerText(voucherLineId)) {
      throw invalid('상계 대상 전표 분개를 선택해 주세요.');
    }
    if (
      offsetAmount === undefined ||
      offsetAmount === null ||
      offsetAmount === '' ||
      typeof offsetAmount === 'boolean' ||
      !Number.isFinite(Number(offsetAmount)) ||
      Number(offsetAmount) <= 0
    ) {
      throw invalid('상계금액은 0보다 큰 숫자여야 합니다.');
    }
    return transaction(async (db) => {
      const lines = await db.query(
        'SELECT vl.account_item_id AS "accountItemId", vl.partner_id AS "partnerId", ' +
          'vl.project_id AS "projectId", vl.dc_type AS "dcType", ' +
          'jv.status AS "voucherStatus", ' +
          BALANCE_SQL +
          ' AS "balance" ' +
          'FROM voucher_line vl ' +
          'JOIN journal_voucher jv ON jv.journal_voucher_id = vl.journal_voucher_id ' +
          'WHERE vl.voucher_line_id = CAST(:voucherLineId AS bigint) ' +
          'FOR UPDATE',
        { voucherLineId: String(voucherLineId) },
      );
      if (lines.length === 0) {
        throw new ApiError(404, 'VOUCHER_LINE_NOT_FOUND', '상계 대상 채권·채무를 찾을 수 없습니다.');
      }
      const line = lines[0];
      if (line['voucherStatus'] === '마감') {
        throw new ApiError(409, 'CLOSED_PERIOD_OFFSET', '마감된 기간의 데이터는 상계할 수 없습니다.');
      }
      if (Number(offsetAmount) > Number(line['balance'])) {
        throw new ApiError(422, 'OFFSET_AMOUNT_EXCEEDED', '상계 금액이 잔액을 초과했습니다.');
      }
      const isDebit = line['dcType'] === 'DEBIT';
      // 가정: 상계 전표는 원 분개와 반대 차대로 같은 계정에 반영한다.
      const vouchers = await db.query(
        'INSERT INTO journal_voucher (voucher_date, source_type, status, debit_total, credit_total, created_at, updated_at) ' +
          "VALUES (CAST(now() AS date), 'AUTO', '승인', CAST(:debit AS numeric), CAST(:credit AS numeric), now(), now()) " +
          'RETURNING journal_voucher_id AS "journalVoucherId"',
        {
          debit: isDebit ? '0' : String(offsetAmount),
          credit: isDebit ? String(offsetAmount) : '0',
        },
      );
      const journalVoucherId = String(vouchers[0]['journalVoucherId']);
      await db.execute(
        'INSERT INTO voucher_line (journal_voucher_id, account_item_id, partner_id, project_id, line_no, dc_type, amount, summary, created_at, updated_at) ' +
          "VALUES (CAST(:journalVoucherId AS bigint), CAST(:accountItemId AS bigint), CAST(:partnerId AS bigint), CAST(:projectId AS bigint), 1, :dcType, CAST(:amount AS numeric), '채권·채무 상계', now(), now())",
        {
          journalVoucherId,
          accountItemId: String(line['accountItemId']),
          partnerId: line['partnerId'] === null ? null : String(line['partnerId']),
          projectId: line['projectId'] === null ? null : String(line['projectId']),
          dcType: isDebit ? 'CREDIT' : 'DEBIT',
          amount: String(offsetAmount),
        },
      );
      const offsets = await db.query(
        'INSERT INTO receivable_offset (voucher_line_id, journal_voucher_id, offset_date, offset_amount, created_at, updated_at) ' +
          'VALUES (CAST(:voucherLineId AS bigint), CAST(:journalVoucherId AS bigint), CAST(now() AS date), CAST(:amount AS numeric), now(), now()) ' +
          'RETURNING receivable_offset_id AS "receivableOffsetId", journal_voucher_id AS "journalVoucherId"',
        { voucherLineId: String(voucherLineId), journalVoucherId, amount: String(offsetAmount) },
      );
      return {
        receivableOffsetId: Number(offsets[0]['receivableOffsetId']),
        journalVoucherId: Number(offsets[0]['journalVoucherId']),
      };
    });
  }
}

