import { useState } from 'react';
import {
  call,
  useData,
  Badge,
  Num,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Pairs,
  Tiles,
  Form,
  Field,
  NumberInput,
  LookupSelect,
  ErrorText,
} from '../kit';
import type { PageProps, Row, Page } from '../kit';

const SIZE = 20;

function today(): string {
  return new Date().toISOString().slice(0, 10);
}

export default function FnSfr00808Page({ role, notify }: PageProps) {
  const [baseDate, setBaseDate] = useState(today());
  const [partnerId, setPartnerId] = useState<number | string>('');
  const [accountItemId, setAccountItemId] = useState<number | string>('');
  const [query, setQuery] = useState<Row>({ baseDate: today() });
  const [page, setPage] = useState(0);
  const [target, setTarget] = useState<Row | null>(null);
  const [amount, setAmount] = useState<number | string>('');

  const { data, error, loading, reload } = useData<Page>(
    () => call<Page>('GET', '/receivable-balances', role, undefined, { ...query, page, size: SIZE }),
    [role, query, page],
  );

  const rows = data ? data.items : [];
  const pageTotal = rows.reduce((sum, row) => sum + Number(row['balance'] ?? 0), 0);

  function search() {
    if (!baseDate) {
      notify('기준일자를 입력해 주세요.');
      return;
    }
    setPage(0);
    setQuery({ baseDate, partnerId, accountItemId });
  }

  function reset() {
    setBaseDate(today());
    setPartnerId('');
    setAccountItemId('');
    setPage(0);
    setQuery({ baseDate: today() });
  }

  function openOffset(row: Row) {
    setAmount('');
    setTarget(row);
  }

  async function submit() {
    if (!target) {
      return;
    }
    if (amount === '' || Number(amount) <= 0) {
      throw new Error('상계금액을 0보다 큰 숫자로 입력해 주세요.');
    }
    await call('POST', '/receivable-offsets', role, {
      voucherLineId: target['voucherLineId'],
      offsetAmount: amount,
    });
    notify('상계 처리했습니다.');
    setTarget(null);
    reload();
  }

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>잔액 현황</h2>
        <Tiles
          items={[
            ['조회 건수', <Num value={data ? data.total : 0} />],
            ['현재 쪽 잔액 합계', <Num value={pageTotal} />],
          ]}
        />
      </section>
      <section className="box span-8">
        <h2>채권·채무 잔액</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="기준일자" required>
            <input type="date" value={baseDate} onChange={(e) => setBaseDate(e.target.value)} />
          </Field>
          <Field label="거래처">
            <LookupSelect table="partner" role={role} value={partnerId} onChange={setPartnerId} />
          </Field>
          <Field label="계정과목">
            <LookupSelect
              table="account_item"
              role={role}
              value={accountItemId}
              onChange={setAccountItemId}
            />
          </Field>
        </Filters>
        <Band total={data ? data.total : 0} />
        {error ? <ErrorText text={error} /> : null}
        <DataTable
          columns={[
            { key: 'voucherLineId', label: '전표 분개 내역 ID' },
            { key: 'partnerName', label: '거래처 명칭' },
            { key: 'accountName', label: '계정과목 명칭' },
            { key: 'balance', label: '채권·채무 잔액', render: (row) => <Num value={row['balance']} /> },
            { key: 'agingBucket', label: '연령분석 기간 구간', render: (row) => <Badge value={row['agingBucket']} /> },
            {
              key: 'action',
              label: '처리',
              render: (row) => (
                <button type="button" onClick={() => openOffset(row)}>
                  상계
                </button>
              ),
            },
          ]}
          rows={rows}
          empty={loading ? '불러오는 중입니다.' : '조회된 채권·채무가 없습니다.'}
        />
        <Pager page={page} size={SIZE} total={data ? data.total : 0} onPage={setPage} />
      </section>
      <section className="box span-4">
        <h2>연령 구간 건수</h2>
        <Pairs
          items={['30일 이내', '31~60일', '61~90일', '90일 초과'].map((name): [string, React.ReactNode] => [
            name,
            <Num value={rows.filter((row) => row['agingBucket'] === name).length} />,
          ])}
        />
      </section>
      {target ? (
        <Drawer title="채권·채무 상계" onClose={() => setTarget(null)}>
          <Pairs
            items={[
              ['전표 분개 내역 ID', String(target['voucherLineId'])],
              ['거래처 명칭', String(target['partnerName'] ?? '')],
              ['계정과목 명칭', String(target['accountName'] ?? '')],
              ['채권·채무 잔액', <Num value={target['balance']} />],
            ]}
          />
          <Form onSubmit={submit} submit="상계 처리">
            <Field label="상계금액" required>
              <NumberInput value={amount} onChange={setAmount} />
            </Field>
          </Form>
        </Drawer>
      ) : null}
    </div>
  );
}
